changeSet.sql:
if (OBJECT_ID('[security].[RuleThen]') > 0 and OBJECT_ID('dbo.ResponsibilityTypeRelationRule') > 0) begin drop table if exists #TempRuleThen_0506;
select cast(r.ID as int) ID, row_number() over(partition by r.Id order by r.Id) as [Position], iif(ti.FieldTypeID = 0 and ti.FieldTypeName = 'Name', 1, ti.[Operator]) as Operator, iif(ti.FieldTypeID > 0, ti.FieldTypeID, null) as FieldTypeId, iif(ti.FieldTypeID > 0, ti.[Value], null) as [Value], iif(ti.FieldTypeID = 0 and ti.FieldTypeName = 'Name', ti.[Value], null) as SecurityId into #TempRuleThen_0506 from ResponsibilityTypeRelationRule r cross apply openjson(r.Definition) with ( [Then] nvarchar(max) as json ) d cross apply openjson(d.[Then]) with ( --Object varchar(50), --ObjectID int, Conditions nvarchar(max) as json ) t cross apply openjson(t.[Conditions]) with ( [Operator] varchar(25), [FieldTypeID] int, FieldTypeName nvarchar(250), [Value] nvarchar(500)--, --IntersectTypeID int, --TargetObject varchar(50), --TargetObjectID int ) ti;
if exists(select 1 from #TempRuleThen_0506) begin
drop table if exists #tempduplicate_0506;
select r.id,r.SecurityId,MIN([Position]) minposition into #tempduplicate_0506 from #TempRuleThen_0506 r group by r.id,r.SecurityId having COUNT(1)>1
delete r from #TempRuleThen_0506 r inner join #tempduplicate_0506 d on r.ID = d.ID and r.SecurityId = d.SecurityId where r.Position > d.minposition;
delete from [security].RuleThen;
insert into [security].RuleThen select r.ID, r.[Position], r.Operator, r.FieldTypeId, r.[Value], r.SecurityId from #TempRuleThen_0506 r; end end

if (OBJECT_ID('[security].[RuleWhen]') > 0 and OBJECT_ID('dbo.ResponsibilityTypeRelationRule') > 0) begin drop table if exists #TempRuleWhen_0506;
select cast(r.Id as int) Id, row_number() over(partition by r.Id order by r.Id) as [Position], wi.CheckType, iif(wi.FieldTypeID > 0, wi.FieldTypeId, null) as FieldTypeId, iif(wi.IntersectTypeID > 0, wi.IntersectTypeID, null) as IntersectTypeId, iif( wi.IntersectTypeID > 0, 1, case wi.[Operator] when 'NotEquals' then 2 when 'Contains' then 3 when 'NotContains' then 4 when 'StartsWith' then 5 when 'EndsWith' then 6 when 'Before' then 7 when 'After' then 8 when 'Between' then 9 when 'Populated' then 10 when 'NotPopulated' then 11 when 'GreaterThan' then 12 when 'LessThanOrEquals' then 13 when 'LessThan' then 14 when 'GreaterThanOrEquals' then 15 when 'In' then 16 when 'NotIn' then 17 when 'IsTrue' then 18 when 'IsFalse' then 19 when 'OnOrBefore' then 20 when 'OnOrAfter' then 21 when 'IsInBand' then 22 else 1 end ) as [Operator], iif(wi.FieldTypeID > 0, wi.[Value], null) as [Value], a.Id as AssetId into #TempRuleWhen_0506 from ResponsibilityTypeRelationRule r cross apply openjson(r.Definition) with ( [When] nvarchar(max) as json ) w cross apply openjson(w.[When]) with ( [CheckType] char(1), [Operator] varchar(25), [FieldTypeID] int, FieldTypeName nvarchar(250), [Value] nvarchar(500), IntersectTypeID int, TargetObject varchar(50), TargetObjectID int ) wi left join Asset a on a.Object = wi.TargetObject and a.ObjectID = wi.TargetObjectID;
if exists(select 1 from #TempRuleWhen_0506) begin truncate table [security].RuleWhen; insert into [security].RuleWhen select r.Id, r.[Position], r.CheckType, r.FieldTypeId, r.IntersectTypeId, r.[Operator], r.[Value], r.AssetId from #TempRuleWhen_0506 r; end end
